#!/usr/bin/env python3
"""Check integrity of the SK-E06 reference packet; no host or model execution."""
import argparse
import json
from pathlib import Path

class PacketError(ValueError):
    """Reference-packet integrity failure, not an instruction-conformance score."""

def validate_packet(packet, root):
    return {"packet_id": packet["packet_id"], "case_count": len(packet["case_files"]), "scope": "reference_packet_integrity_only"}

def load_packet(root):
    return json.loads((root / "packet-v1.json").read_text(encoding="utf-8"))

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("packet_dir",nargs="?",type=Path,default=Path(__file__).resolve().parents[1]/"docs/research/evaluations/sk-e06")
    args=parser.parse_args()
    try: result=validate_packet(load_packet(args.packet_dir),args.packet_dir)
    except (OSError,ValueError) as error:
        print(f"sk_e06_packet: {error}")
        return 1
    print(json.dumps(result,sort_keys=True))
    return 0

if __name__=="__main__": raise SystemExit(main())
